/** @param {string} text */
function esc(text){return text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
/** @param {string} iso */
function dateLabel(iso){return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(iso));}
/** @param {string} action @param {string} text @param {string} [kind] @param {string} [extra] */
function button(action,text,kind='',extra=''){return `<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${text}</button>`;}
/** @param {Resume} r */
function cardView(r){return `<article class="resume-card"><div class="paper-thumb" aria-hidden="true"><span class="mini-page"><span class="mini-name">${esc(r.name||'이름을 입력하세요')}</span><span class="mini-summary">${esc(r.summary||'나의 경험을 소개해 보세요.')}</span><span class="mini-section">경력</span><span class="mini-role">${esc(r.experience[0]?.company||'경력을 추가하세요')}</span></span></div><h2>${esc(r.title)}</h2><p class="target">${esc(r.target||'직무 미설정')}</p><div class="card-meta"><span class="badge ${r.status==='ready'?'ready':''}">${r.archived?'보관됨':r.status==='ready'?'작성 완료':'작성 중'}</span><time class="muted" datetime="${r.updated}">${dateLabel(r.updated)} 수정</time></div><div class="card-actions">${button('edit','편집','edit',`data-id="${r.id}"`)}${button('duplicate','복제','quiet',`data-id="${r.id}"`)}${button('archive',r.archived?'꺼내기':'보관','quiet',`data-id="${r.id}"`)}</div></article>`;}
function listView(){return `<main class="workspace"><div class="page-heading"><div><a class="small muted" href="index.html">서비스 소개</a><h1>내 이력서</h1></div>${button('new',`새 이력서 ${icon('plus')}`,'primary')}</div><div class="toolbar"><div class="tabs" aria-label="이력서 상태">${[['all','전체'],['draft','작성 중'],['ready','작성 완료'],['archived','보관']].map(([key,label])=>`<button class="tab" data-filter="${key}" aria-pressed="${filter===key}">${label}</button>`).join('')}</div><label class="search"><span class="small muted">검색</span><input type="search" id="search" aria-label="이력서 검색" placeholder="제목 또는 직무" value="${esc(query)}"></label></div><div id="cards" class="grid">${cardsView()}</div><div class="storage-note"><span>이 브라우저에 저장돼요. 첫 이력서 3개는 편집 가능한 예시예요.</span>${button('backup-all','전체 백업','quiet')}${button('import','백업 불러오기','quiet')}<input id="import-file" type="file" accept="application/json,.json" hidden></div></main>`;}
function cardsView(){const list=resumes.filter(r=>(filter==='archived'?r.archived:!r.archived&&(filter==='all'||r.status===filter))&&`${r.title} ${r.target}`.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(cardView).join(''):`<section class="empty"><h2>${query?'검색 결과가 없어요':filter==='archived'?'보관한 이력서가 없어요':'아직 이력서가 없어요'}</h2><p>${query?'다른 제목이나 직무로 찾아보세요.':'새 이력서를 만들거나 다른 상태의 문서를 확인해 보세요.'}</p>${query?button('clear-search','검색 초기화','primary'):''}</section>`;}
/** @param {string} label @param {string} key @param {string} value @param {string} [type] @param {string} [cls] */
function field(label,key,value,type='text',cls=''){if(type==='month')return `<div class="field ${cls}"><span>${label}</span><button class="month-input" data-action="month" data-month-key="${key}" data-month-value="${value}" aria-label="${label}">${value?`${value.slice(0,4)}년 ${Number(value.slice(5))}월`:'선택 안 함'}</button></div>`;return `<label class="field ${cls}"><span>${label}</span>${type==='textarea'?`<textarea data-field="${key}">${esc(value)}</textarea>`:`<input type="${type}" data-field="${key}" value="${esc(value)}" ${type==='month'?'':`autocomplete="off"`}>`}</label>`;}
/** @param {Resume} r */
function editorView(r){return `${topView(r,false)}<div class="editor-layout"><nav class="section-nav" aria-label="이력서 항목"><h2>이력서 항목</h2>${[['basic','기본 정보'],['summary','소개'],['experience','경력'],['education','학력'],['skills','스킬'],['target','지원 준비']].map(([id,label])=>`<a href="#${id}" ${id==='basic'?'aria-current="true"':''}>${label}</a>`).join('')}${button('history','버전 기록')}${button('review','작성 점검')}</nav><main class="document" aria-label="이력서 편집"><section id="basic" class="document-section"><div class="section-title"><h2>기본 정보</h2><label class="field"><span>작성 상태</span><select class="status-select" data-status><option value="draft" ${r.status==='draft'?'selected':''}>작성 중</option><option value="ready" ${r.status==='ready'?'selected':''}>작성 완료</option></select></label></div><div class="fields">${field('이력서 제목','title',r.title,'text','full')}${field('이름','name',r.name)}${field('지원 직무','target',r.target)}${field('이메일','email',r.email,'email')}${field('연락처','phone',r.phone,'tel')}${field('포트폴리오 링크','link',r.link,'text','full')}</div></section><section id="summary" class="document-section"><div class="section-title"><h2>소개</h2></div>${field('어떤 경험과 강점을 가진 사람인가요?','summary',r.summary,'textarea')}</section><section id="experience" class="document-section"><div class="section-title"><h2>경력</h2>${button('add-experience',`경력 추가 ${icon('plus')}`)}</div>${r.experience.length?r.experience.map((e,i)=>`<div class="entry"><div class="entry-head"><h3>경력 ${i+1}</h3>${button('remove-experience','삭제','quiet',`data-index="${i}"`)}</div><div class="fields">${field('회사명',`experience.${i}.company`,e.company)}${field('직무·직책',`experience.${i}.role`,e.role)}${field('입사월',`experience.${i}.start`,e.start,'month')}${field('퇴사월 · 재직 중이면 비워두세요',`experience.${i}.end`,e.end,'month')}${field('담당한 일과 성과',`experience.${i}.description`,e.description,'textarea','full')}</div></div>`).join(''):'<p class="section-empty">경력이 없다면 프로젝트 경험을 적어도 좋아요.</p>'}</section><section id="education" class="document-section"><div class="section-title"><h2>학력</h2>${button('add-education',`학력 추가 ${icon('plus')}`)}</div>${r.education.length?r.education.map((e,i)=>`<div class="entry"><div class="entry-head"><h3>학력 ${i+1}</h3>${button('remove-education','삭제','quiet',`data-index="${i}"`)}</div><div class="fields">${field('학교명',`education.${i}.school`,e.school)}${field('전공·학위',`education.${i}.major`,e.major)}${field('입학월',`education.${i}.start`,e.start,'month')}${field('졸업월 · 재학 중이면 비워두세요',`education.${i}.end`,e.end,'month')}</div></div>`).join(''):'<p class="section-empty">학력을 추가하면 문서에 함께 표시돼요.</p>'}</section><section id="skills" class="document-section"><div class="section-title"><h2>스킬</h2></div>${field('쉼표로 구분해 입력하세요','skills',r.skills,'textarea')}</section><section id="target" class="document-section"><div class="section-title"><h2>지원 준비</h2>${button('match','공고와 대조')}</div>${field('채용공고의 요구사항 · 출력 문서에는 포함되지 않아요','job',r.job,'textarea')}<p class="small" style="margin-top:var(--s3)">지원처별로 복제하면 기본 이력서를 보존할 수 있어요.</p></section></main></div>`;}
/** @param {Resume} r @param {boolean} preview */
function topView(r,preview){return `<header class="topbar">${button(preview?'edit-current':'list',preview?'편집으로':'목록으로','quiet')}<h1 class="doc-title">${esc(r.title)}</h1><div class="actions">${preview?button('backup','백업')+button('print','인쇄 · PDF','primary'):`<span class="saved" role="status">${storageMessage?'저장 확인 필요':'브라우저에 저장됨'}</span>${button('save-version','버전 저장')}${button('preview','미리보기','primary')}`}</div></header>`;}
/** @param {string} start @param {string} end @param {string} ongoing */
function period(start,end,ongoing){return `${start||'시작월 미입력'} – ${end||ongoing}`;}
/** @param {Resume} r */
function previewView(r){return `${topView(r,true)}<main class="preview-wrap"><article class="document print-document"><h1>${esc(r.name||'이름 미입력')}</h1><p>${esc(r.target)}</p><div class="contact">${[r.email,r.phone,r.link].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${r.summary?`<section class="print-section"><h2>소개</h2><p>${esc(r.summary)}</p></section>`:''}${r.experience.length?`<section class="print-section"><h2>경력</h2>${r.experience.map(e=>`<div class="print-entry"><h3>${esc(e.company)} · ${esc(e.role)}</h3><p class="date">${esc(period(e.start,e.end,'재직 중'))}</p><p>${esc(e.description)}</p></div>`).join('')}</section>`:''}${r.education.length?`<section class="print-section"><h2>학력</h2>${r.education.map(e=>`<div class="print-entry"><h3>${esc(e.school)}</h3><p>${esc(e.major)}</p><p class="date">${esc(period(e.start,e.end,'재학 중'))}</p></div>`).join('')}</section>`:''}${r.skills?`<section class="print-section"><h2>스킬</h2><div class="skill-list">${r.skills.split(',').map(x=>x.trim()).filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div></section>`:''}</article></main>`;}
